 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Locate non-background row bands.
    bands = []
    start = None
    for r in range(h + 1):
        active = r < h and any(v != bg for v in grid[r])
        if active and start is None:
            start = r
        elif not active and start is not None:
            bands.append((start, r))
            start = None
    if len(bands) < 2:
        return [row[:] for row in grid]
    # Select the two largest bands, then compare equal-height pattern copies.
    bands = sorted(bands, key=lambda b: b[1]-b[0], reverse=True)[:2]
    bands.sort()
    (a0,a1),(b0,b1)=bands
    n=min(a1-a0,b1-b0)
    out=[row[:] for row in grid]
    if n <= 0:
        return out
    # Find horizontal displacement that best aligns occupied cells.
    best=None
    for d in range(-w+1,w):
        inter=union=0
        for k in range(n):
            A={c for c,v in enumerate(grid[a0+k]) if v!=bg}
            B={c for c,v in enumerate(grid[b0+k]) if v!=bg}
            shifted={c+d for c in A if 0<=c+d<w}
            inter += len(shifted & B)
            union += len(shifted | B)
        score=(inter/union if union else 0, inter, -abs(d))
        if best is None or score>best[0]: best=(score,d)
    d=best[1]
    # Add the missing cells to the copy with fewer foreground cells.
    ca=sum(v!=bg for r in range(a0,a0+n) for v in grid[r])
    cb=sum(v!=bg for r in range(b0,b0+n) for v in grid[r])
    if ca <= cb:
        # A is less populated: infer from B, reverse the displacement.
        for k in range(n):
            for c,v in enumerate(grid[b0+k]):
                src=c-d
                if v==bg and 0<=src<w and grid[a0+k][src]!=bg:
                    out[b0+k][c]=1
    else:
        # B is less populated: infer from A shifted by d.
        for k in range(n):
            for c,v in enumerate(grid[a0+k]):
                dest=c+d
                if v!=bg and 0<=dest<w and grid[b0+k][dest]==bg:
                    out[b0+k][dest]=1
    return out
